import { remove } from 'unist-util-remove';
import { isMdxJsxElement, SMIL_ELEMENT_NAMES } from '../../utils.js';
const SMIL_ELEMENTS = new Set(SMIL_ELEMENT_NAMES.map((name) => name.toLowerCase()));
const ANIMATION_VALUE_ATTRIBUTES = new Set(['values', 'from', 'to', 'by']);
const REFERENCE_ATTRIBUTES = new Set(['href', 'xlink:href', 'xlinkhref']);
const SCRIPTABLE_TARGETS = new Set(['href', 'xlinkhref', 'src', 'style']);
const SCRIPTABLE_URL = /(?:javascript|vbscript|data):/;
const normalize = (value) => Array.from(value)
    .filter((character) => character > ' ')
    .join('')
    .toLowerCase();
const localName = (name) => name.slice(name.lastIndexOf(':') + 1).toLowerCase();
const targetsScriptableAttribute = (attributeName) => {
    const name = localName(attributeName);
    return SCRIPTABLE_TARGETS.has(name) || name.startsWith('on');
};
function isSafeSmilAttribute(attribute) {
    if (attribute.type === 'mdxJsxExpressionAttribute')
        return false;
    const name = attribute.name.toLowerCase();
    if (name.startsWith('on'))
        return false;
    if (typeof attribute.value !== 'string')
        return attribute.value == null;
    const value = normalize(attribute.value);
    if (name === 'attributename')
        return !targetsScriptableAttribute(value);
    if (REFERENCE_ATTRIBUTES.has(name))
        return value.startsWith('#');
    return !ANIMATION_VALUE_ATTRIBUTES.has(name) || !SCRIPTABLE_URL.test(value);
}
export const isUnsafeSmilElement = ({ name, attributes = [] }) => name != null && SMIL_ELEMENTS.has(localName(name)) && !attributes.every(isSafeSmilAttribute);
export const remarkMdxRemoveUnsafeSmil = () => (tree) => {
    remove(tree, { cascade: false }, (node) => isMdxJsxElement(node) && isUnsafeSmilElement(node));
};
